import { Component, OnInit, Input } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule } from '@angular/router';
import { ApiService } from '../../core/services/api.service';
import { ToastService } from '../../core/services/toast.service';

@Component({
  selector: 'app-project-detail',
  standalone: true,
  imports: [CommonModule, RouterModule],
  template: `
    <div class="page-container">

      <!-- HEADER -->
      <div class="page-header">
        <a routerLink="/projects" class="back-link">← Retour aux projets</a>
        <div class="header-row" *ngIf="project">
          <div class="header-left">
            <div class="project-avatar" [style.border-color]="getHealthColor(project.healthScore)">
              {{project.name?.substring(0,2).toUpperCase()}}
            </div>
            <div>
              <h1 class="page-title">// {{project.name}}</h1>
              <p class="page-subtitle">{{project.description || 'Projet DevSecOps sous surveillance IA'}}</p>
            </div>
          </div>
          <div class="header-right">
            <div class="health-ring" [style.--health-color]="getHealthColor(project.healthScore)">
              <span class="health-value">{{project.healthScore | number:'1.0-0'}}%</span>
              <span class="health-label">Santé</span>
            </div>
          </div>
        </div>
      </div>

      <div *ngIf="loading" class="loading-overlay"><div class="spinner"></div></div>

      <ng-container *ngIf="project && !loading">

        <!-- KPIs -->
        <div class="kpi-grid">
          <div class="kpi-card red">
            <div class="kpi-icon">🔴</div>
            <div class="kpi-value">{{project.openIncidents || 0}}</div>
            <div class="kpi-label">Incidents ouverts</div>
          </div>
          <div class="kpi-card blue">
            <div class="kpi-icon">🔵</div>
            <div class="kpi-value">{{project.analyzingIncidents || 0}}</div>
            <div class="kpi-label">En analyse IA</div>
          </div>
          <div class="kpi-card orange">
            <div class="kpi-icon">🟡</div>
            <div class="kpi-value">{{project.proposedIncidents || 0}}</div>
            <div class="kpi-label">Corrections proposées</div>
          </div>
          <div class="kpi-card green">
            <div class="kpi-icon">🟢</div>
            <div class="kpi-value">{{project.resolvedIncidents || 0}}</div>
            <div class="kpi-label">Résolus</div>
          </div>
        </div>

        <!-- TABS -->
        <div class="tabs-row">
          <button class="tab-btn" [class.active]="activeTab === 'rapport'" (click)="activeTab = 'rapport'">
            🤖 Rapport IA
          </button>
          <button class="tab-btn" [class.active]="activeTab === 'incidents'" (click)="activeTab = 'incidents'">
            🚨 Incidents
          </button>
          <button class="tab-btn" [class.active]="activeTab === 'info'" (click)="activeTab = 'info'">
            ℹ️ Informations
          </button>
        </div>

        <!-- ═══════════════════════════════════════
             ONGLET RAPPORT IA
        ════════════════════════════════════════ -->
        <div *ngIf="activeTab === 'rapport'">

          <div *ngIf="!latestReport" class="empty-state">
            <div class="empty-icon">🤖</div>
            <div class="empty-title">Aucun rapport IA disponible</div>
            <div class="empty-sub">Lancez un build Jenkins pour générer un rapport</div>
          </div>

          <div *ngIf="latestReport" class="rapport-container">

            <!-- RAPPORT HEADER -->
            <div class="rapport-hero" [class.block]="rp.decision === 'BLOCK'"
                                      [class.autofix]="rp.decision === 'AUTO_FIX'"
                                      [class.notify]="rp.decision === 'NOTIFY_ONLY'">
              <div class="rapport-hero-left">
                <div class="rapport-build-tag">Build #{{rp.build || '?'}}</div>
                <div class="rapport-title">RAPPORT DEVSECOPS IA</div>
                <div class="rapport-meta">
                  <span>{{latestReport.createdAt | date:'dd/MM/yyyy HH:mm'}}</span>
                  <span class="sep">·</span>
                  <span>{{rp.job || 'N/A'}}</span>
                  <span class="sep">·</span>
                  <span>{{rp.branch || 'N/A'}}</span>
                </div>
              </div>
              <div class="rapport-hero-right">
                <div class="decision-badge" [style.color]="getDecisionColor(rp.decision)"
                     [style.border-color]="getDecisionColor(rp.decision)"
                     [style.background]="getDecisionColor(rp.decision) + '18'">
                  {{rp.decision || 'N/A'}}
                </div>
                <div class="confidence-display">
                  <div class="confidence-bar-wrap">
                    <div class="confidence-bar"
                         [style.width]="rp.confidence || '0%'"
                         [style.background]="getDecisionColor(rp.decision)"></div>
                  </div>
                  <span class="confidence-text">Confiance : {{rp.confidence || '0%'}}</span>
                </div>
                <div class="security-level" [style.color]="getSecurityColor(rp.security)">
                  🔒 {{rp.security || 'UNKNOWN'}}
                </div>
              </div>
            </div>

            <!-- GRILLE RAPPORT -->
            <div class="rapport-grid">

              <!-- ERREURS DÉTECTÉES -->
              <div class="rapport-section error-section" *ngIf="rp.errors">
                <div class="section-header">
                  <span class="section-icon">❌</span>
                  <span class="section-title">ERREURS DÉTECTÉES</span>
                </div>
                <div class="section-body error-body">
                  <p>{{rp.errors}}</p>
                </div>
              </div>

              <!-- CE QUE L'IA A FAIT -->
              <div class="rapport-section agent-section" *ngIf="rp.agentActions">
                <div class="section-header">
                  <span class="section-icon">🤖</span>
                  <span class="section-title">CE QUE LES AGENTS IA ONT FAIT</span>
                </div>
                <div class="section-body">
                  <p>{{rp.agentActions}}</p>
                </div>
              </div>

              <!-- ANALYSE SÉCURITÉ DÉTAILLÉE -->
              <div class="rapport-section security-section" *ngIf="rawSecurity">
                <div class="section-header">
                  <span class="section-icon">🔒</span>
                  <span class="section-title">ANALYSE SÉCURITÉ</span>
                  <span class="risk-pill" [style.color]="getSecurityColor(rawSecurity.riskLevel)"
                        [style.background]="getSecurityColor(rawSecurity.riskLevel) + '18'">
                    {{rawSecurity.riskLevel || 'N/A'}}
                  </span>
                </div>
                <div class="section-body">
                  <div class="security-issues" *ngIf="rawSecurity.securityIssues?.length">
                    <div class="issue-item" *ngFor="let issue of rawSecurity.securityIssues">
                      <span class="issue-dot">⚠</span>
                      <span>{{issue}}</span>
                    </div>
                  </div>
                  <div class="security-rec" *ngIf="rawSecurity.secRecommendation">
                    <span class="rec-label">Recommandation sécurité :</span>
                    {{rawSecurity.secRecommendation}}
                  </div>
                  <div class="safe-badge" *ngIf="rawSecurity.safeToApply !== undefined">
                    <span [class]="rawSecurity.safeToApply ? 'safe-yes' : 'safe-no'">
                      {{rawSecurity.safeToApply ? '✅ Application sûre' : '🚫 Application risquée'}}
                    </span>
                  </div>
                </div>
              </div>

              <!-- PLAN DE REMÉDIATION -->
              <div class="rapport-section remediation-section" *ngIf="rawRemediation">
                <div class="section-header">
                  <span class="section-icon">🔧</span>
                  <span class="section-title">PLAN DE REMÉDIATION</span>
                  <span class="confidence-pill">
                    Confiance IA : {{((rawRemediation.confidence || 0) * 100) | number:'1.0-0'}}%
                  </span>
                </div>
                <div class="section-body">
                  <p class="fix-description" *ngIf="rawRemediation.fixDescription">
                    {{rawRemediation.fixDescription}}
                  </p>
                  <div class="fix-steps" *ngIf="rawRemediation.fixSteps?.length">
                    <div class="fix-step" *ngFor="let step of rawRemediation.fixSteps; let i = index">
                      <span class="step-number">{{i + 1}}</span>
                      <span>{{step}}</span>
                    </div>
                  </div>
                  <div class="autofix-badge" *ngIf="rawRemediation.autoFixable !== undefined">
                    <span [class]="rawRemediation.autoFixable ? 'autofix-yes' : 'autofix-no'">
                      {{rawRemediation.autoFixable ? '🤖 Correction automatique possible' : '👨‍💻 Correction manuelle requise'}}
                    </span>
                  </div>
                </div>
              </div>

              <!-- CHECKLIST DÉVELOPPEUR -->
              <div class="rapport-section developer-section full-width">
                <div class="section-header">
                  <span class="section-icon">👨‍💻</span>
                  <span class="section-title">CE QUE LE DÉVELOPPEUR DOIT FAIRE</span>
                  <span class="checklist-progress" *ngIf="devTasks.length">
                    {{checkedTasks}}/{{devTasks.length}} complétées
                  </span>
                </div>
                <div class="section-body">
                  <div *ngIf="devTasks.length === 0" class="no-tasks">
                    <span style="color:var(--text-faint);">{{rp.developerActions || 'Aucune action requise'}}</span>
                  </div>
                  <div class="checklist" *ngIf="devTasks.length > 0">
                    <div class="checklist-item" *ngFor="let task of devTasks; let i = index"
                         [class.checked]="task.done" (click)="toggleTask(i)">
                      <div class="checkbox" [class.checked]="task.done">
                        <span *ngIf="task.done">✓</span>
                      </div>
                      <div class="task-content">
                        <span class="task-text" [class.done]="task.done">{{task.text}}</span>
                        <span class="priority-tag" *ngIf="task.priority"
                              [class]="'priority-' + task.priority.toLowerCase()">
                          {{task.priority}}
                        </span>
                      </div>
                    </div>
                  </div>
                  <div class="progress-bar-wrap" *ngIf="devTasks.length > 0">
                    <div class="progress-bar">
                      <div [style.width]="(checkedTasks / devTasks.length * 100) + '%'"></div>
                    </div>
                  </div>
                </div>
              </div>

              <!-- RECOMMANDATIONS -->
              <div class="rapport-section reco-section full-width" *ngIf="rp.recommendations">
                <div class="section-header">
                  <span class="section-icon">💡</span>
                  <span class="section-title">RECOMMANDATIONS</span>
                </div>
                <div class="section-body">
                  <p>{{rp.recommendations}}</p>
                </div>
              </div>

              <!-- RAISON DE LA DÉCISION -->
              <div class="rapport-section reason-section full-width" *ngIf="rp.reason">
                <div class="section-header">
                  <span class="section-icon">📝</span>
                  <span class="section-title">RAISON DE LA DÉCISION</span>
                </div>
                <div class="section-body">
                  <p class="reason-text">{{rp.reason}}</p>
                </div>
              </div>

            </div>

            <!-- FOOTER -->
            <div class="rapport-footer">
              <span style="font-size:10px;color:var(--text-faint);font-family:var(--font-mono);">
                Généré par Claude claude-opus-4-5 (Judge) + llama3.2:3b (Agents) · Score sécurité: {{latestReport.securityScore}}% · Risque: {{latestReport.riskLevel}}
              </span>
              <button class="btn btn-secondary btn-sm" (click)="copyReport()">📋 Copier le rapport</button>
            </div>

          </div>

          <!-- HISTORIQUE DES RAPPORTS -->
          <div class="history-section" *ngIf="allReports.length > 1">
            <div class="history-title">📊 Historique des rapports</div>
            <div class="history-list">
              <div class="history-item" *ngFor="let r of allReports; let i = index"
                   [class.active]="latestReport?.id === r.id"
                   (click)="selectReport(r)">
                <div class="history-build">Build #{{parseReport(r.aiSummary).build || '?'}}</div>
                <div class="history-decision"
                     [style.color]="getDecisionColor(parseReport(r.aiSummary).decision)">
                  {{parseReport(r.aiSummary).decision || 'N/A'}}
                </div>
                <div class="history-date">{{r.createdAt | date:'dd/MM HH:mm'}}</div>
              </div>
            </div>
          </div>

        </div>

        <!-- ═══════════════════════════════════════
             ONGLET INCIDENTS
        ════════════════════════════════════════ -->
        <div *ngIf="activeTab === 'incidents'">
          <div class="card">
            <div class="card-header">
              <span class="card-title">Incidents du projet</span>
              <a [routerLink]="['/incidents']" [queryParams]="{projectId: project.id}"
                 class="btn btn-secondary btn-sm">Voir tous →</a>
            </div>
            <div *ngIf="incidents.length === 0" class="empty-state" style="padding:20px;">
              <div class="empty-title">Aucun incident</div>
            </div>
            <div *ngFor="let inc of incidents" class="inc-row">
              <span class="badge {{inc.severity?.toLowerCase()}}">{{inc.severity}}</span>
              <span style="flex:1;font-size:11px;color:var(--text-secondary);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">
                {{inc.title || inc.sourceType}}
              </span>
              <span class="badge {{inc.status?.toLowerCase()}}">{{inc.status}}</span>
              <span style="font-size:10px;color:var(--text-faint);font-family:var(--font-mono);">
                {{inc.createdAt | date:'dd/MM HH:mm'}}
              </span>
            </div>
          </div>
        </div>

        <!-- ═══════════════════════════════════════
             ONGLET INFORMATIONS
        ════════════════════════════════════════ -->
        <div *ngIf="activeTab === 'info'">
          <div class="card">
            <div class="card-header"><span class="card-title">Informations du projet</span></div>
            <table style="width:100%;">
              <tr *ngFor="let info of getInfoRows()">
                <td style="font-size:11px;color:var(--text-faint);padding:8px 0;width:35%;">{{info.label}}</td>
                <td style="font-size:12px;color:var(--text-secondary);font-family:var(--font-mono);">{{info.value}}</td>
              </tr>
            </table>
          </div>
        </div>

      </ng-container>
    </div>
  `,
  styles: [`
    .back-link {
      font-size: 12px; color: var(--text-muted); text-decoration: none;
      &:hover { color: var(--text-secondary); }
    }
    .header-row {
      display: flex; align-items: center; justify-content: space-between;
      margin-top: 12px; gap: 16px;
    }
    .header-left { display: flex; align-items: center; gap: 14px; }
    .project-avatar {
      width: 48px; height: 48px; border-radius: var(--radius-md);
      background: var(--bg-tertiary); border: 2px solid;
      display: flex; align-items: center; justify-content: center;
      font-size: 16px; font-weight: 700; font-family: var(--font-mono);
      color: var(--text-secondary); flex-shrink: 0;
    }
    .health-ring {
      display: flex; flex-direction: column; align-items: center;
      padding: 12px 20px; border-radius: var(--radius-md);
      background: var(--bg-secondary); border: 1px solid var(--border);
      border-top: 3px solid var(--health-color, var(--accent-green));
    }
    .health-value { font-size: 22px; font-weight: 700; font-family: var(--font-mono); color: var(--health-color, var(--accent-green)); }
    .health-label { font-size: 10px; color: var(--text-faint); text-transform: uppercase; letter-spacing: 1px; }

    .kpi-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 12px; margin-bottom: 20px; }
    .kpi-card {
      background: var(--bg-secondary); border: 1px solid var(--border);
      border-radius: var(--radius-lg); padding: 16px; text-align: center;
      &.red    { border-top: 2px solid var(--accent-red); }
      &.blue   { border-top: 2px solid var(--accent-blue); }
      &.orange { border-top: 2px solid var(--accent-orange); }
      &.green  { border-top: 2px solid var(--accent-green); }
    }
    .kpi-icon { font-size: 18px; margin-bottom: 6px; }
    .kpi-value { font-size: 28px; font-weight: 700; font-family: var(--font-mono); color: var(--text-primary); }
    .kpi-label { font-size: 10px; color: var(--text-faint); text-transform: uppercase; letter-spacing: 0.5px; margin-top: 4px; }

    .tabs-row { display: flex; gap: 8px; margin-bottom: 20px; border-bottom: 1px solid var(--border); padding-bottom: 0; }
    .tab-btn {
      padding: 8px 16px; font-size: 12px; color: var(--text-muted);
      background: transparent; border: none; border-bottom: 2px solid transparent;
      cursor: pointer; transition: all 0.15s; margin-bottom: -1px;
      &:hover { color: var(--text-secondary); }
      &.active { color: var(--accent-blue); border-bottom-color: var(--accent-blue); font-weight: 600; }
    }

    /* ─── RAPPORT ─── */
    .rapport-container { display: flex; flex-direction: column; gap: 16px; }

    .rapport-hero {
      background: var(--bg-secondary); border: 1px solid var(--border);
      border-radius: var(--radius-lg); padding: 24px;
      display: flex; align-items: flex-start; justify-content: space-between; gap: 20px;
      &.block  { border-left: 4px solid var(--accent-red); }
      &.autofix { border-left: 4px solid var(--accent-green); }
      &.notify { border-left: 4px solid var(--accent-orange); }
    }
    .rapport-hero-left { display: flex; flex-direction: column; gap: 6px; }
    .rapport-build-tag {
      display: inline-block; font-size: 10px; font-family: var(--font-mono);
      color: var(--accent-blue); background: var(--accent-blue)18;
      padding: 2px 8px; border-radius: 4px; border: 1px solid var(--accent-blue)44;
    }
    .rapport-title { font-size: 18px; font-weight: 700; font-family: var(--font-mono); color: var(--text-primary); }
    .rapport-meta { display: flex; gap: 8px; font-size: 11px; color: var(--text-faint); align-items: center; }
    .sep { color: var(--border-light); }
    .rapport-hero-right { display: flex; flex-direction: column; align-items: flex-end; gap: 10px; }
    .decision-badge {
      font-size: 13px; font-weight: 700; padding: 6px 16px;
      border-radius: 20px; border: 1px solid; font-family: var(--font-mono);
    }
    .confidence-bar-wrap {
      width: 140px; height: 4px; background: var(--border);
      border-radius: 2px; overflow: hidden;
    }
    .confidence-bar { height: 100%; border-radius: 2px; transition: width 0.8s ease; }
    .confidence-text { font-size: 10px; color: var(--text-faint); font-family: var(--font-mono); }
    .confidence-display { display: flex; flex-direction: column; gap: 4px; align-items: flex-end; }
    .security-level { font-size: 12px; font-weight: 600; }

    .rapport-grid {
      display: grid; grid-template-columns: 1fr 1fr; gap: 12px;
    }
    .rapport-section {
      background: var(--bg-secondary); border: 1px solid var(--border);
      border-radius: var(--radius-md); overflow: hidden;
      &.full-width { grid-column: 1 / -1; }
      &.error-section { border-top: 2px solid var(--accent-red); }
      &.agent-section { border-top: 2px solid var(--accent-blue); }
      &.security-section { border-top: 2px solid var(--accent-orange); }
      &.remediation-section { border-top: 2px solid var(--accent-purple, #a78bfa); }
      &.developer-section { border-top: 2px solid var(--accent-yellow, #f59e0b); border-left: 3px solid var(--accent-yellow, #f59e0b); }
      &.reco-section { border-top: 2px solid var(--accent-green); }
      &.reason-section { background: var(--bg-hover); }
    }
    .section-header {
      display: flex; align-items: center; gap: 8px;
      padding: 10px 14px; border-bottom: 1px solid var(--border);
      background: var(--bg-hover);
    }
    .section-icon { font-size: 14px; }
    .section-title {
      font-size: 10px; font-weight: 700; color: var(--text-muted);
      letter-spacing: 1px; text-transform: uppercase; font-family: var(--font-mono); flex: 1;
    }
    .risk-pill {
      font-size: 10px; font-weight: 700; padding: 2px 8px;
      border-radius: 10px; font-family: var(--font-mono);
    }
    .confidence-pill {
      font-size: 10px; color: var(--text-faint); font-family: var(--font-mono);
    }
    .checklist-progress {
      font-size: 10px; color: var(--accent-green); font-family: var(--font-mono); font-weight: 600;
    }
    .section-body { padding: 14px; font-size: 12px; color: var(--text-secondary); line-height: 1.7; }
    .error-body { color: var(--accent-red); }

    .security-issues { display: flex; flex-direction: column; gap: 6px; margin-bottom: 10px; }
    .issue-item { display: flex; gap: 8px; align-items: flex-start; font-size: 12px; }
    .issue-dot { color: var(--accent-orange); flex-shrink: 0; }
    .security-rec { font-size: 11px; color: var(--text-faint); margin-top: 8px; padding-top: 8px; border-top: 1px solid var(--border); }
    .rec-label { font-weight: 600; color: var(--text-muted); }
    .safe-badge { margin-top: 8px; }
    .safe-yes { font-size: 11px; color: var(--accent-green); }
    .safe-no  { font-size: 11px; color: var(--accent-red); }

    .fix-description { margin-bottom: 10px; }
    .fix-steps { display: flex; flex-direction: column; gap: 8px; }
    .fix-step {
      display: flex; gap: 10px; align-items: flex-start;
      padding: 8px; background: var(--bg-hover); border-radius: var(--radius-sm);
      font-size: 12px;
    }
    .step-number {
      width: 20px; height: 20px; border-radius: 50%;
      background: var(--accent-purple, #a78bfa); color: #000;
      display: flex; align-items: center; justify-content: center;
      font-size: 10px; font-weight: 700; flex-shrink: 0;
    }
    .autofix-badge { margin-top: 10px; }
    .autofix-yes { font-size: 11px; color: var(--accent-green); }
    .autofix-no  { font-size: 11px; color: var(--accent-orange); }

    .checklist { display: flex; flex-direction: column; gap: 8px; }
    .checklist-item {
      display: flex; align-items: flex-start; gap: 10px;
      padding: 10px 12px; background: var(--bg-hover);
      border-radius: var(--radius-sm); cursor: pointer;
      border: 1px solid var(--border); transition: all 0.15s;
      &:hover { border-color: var(--border-light); }
      &.checked { opacity: 0.6; background: var(--bg-tertiary); }
    }
    .checkbox {
      width: 18px; height: 18px; border: 1px solid var(--border-light);
      border-radius: 4px; display: flex; align-items: center; justify-content: center;
      font-size: 11px; flex-shrink: 0; transition: all 0.15s;
      &.checked { background: var(--accent-green); border-color: var(--accent-green); color: #000; }
    }
    .task-content { display: flex; align-items: center; gap: 8px; flex: 1; flex-wrap: wrap; }
    .task-text { font-size: 12px; color: var(--text-secondary); flex: 1; &.done { text-decoration: line-through; color: var(--text-faint); } }
    .priority-tag {
      font-size: 9px; font-weight: 700; padding: 2px 6px; border-radius: 8px;
      font-family: var(--font-mono); text-transform: uppercase;
      &.priority-haute  { background: var(--accent-red)22;    color: var(--accent-red); }
      &.priority-moyenne { background: var(--accent-orange)22; color: var(--accent-orange); }
      &.priority-basse  { background: var(--accent-green)22;  color: var(--accent-green); }
    }
    .progress-bar-wrap { margin-top: 12px; }
    .progress-bar {
      height: 3px; background: var(--border); border-radius: 2px; overflow: hidden;
      div { height: 100%; background: var(--accent-green); border-radius: 2px; transition: width 0.4s ease; }
    }

    .reason-text { font-family: var(--font-mono); font-size: 11px; color: var(--text-faint); }

    .rapport-footer {
      display: flex; justify-content: space-between; align-items: center;
      padding: 12px 16px; background: var(--bg-secondary);
      border: 1px solid var(--border); border-radius: var(--radius-md);
    }

    .history-section { margin-top: 20px; }
    .history-title { font-size: 11px; color: var(--text-muted); font-family: var(--font-mono); margin-bottom: 8px; font-weight: 700; text-transform: uppercase; letter-spacing: 1px; }
    .history-list { display: flex; gap: 8px; flex-wrap: wrap; }
    .history-item {
      display: flex; gap: 8px; align-items: center;
      padding: 6px 12px; background: var(--bg-secondary);
      border: 1px solid var(--border); border-radius: var(--radius-md);
      cursor: pointer; font-size: 11px; transition: all 0.15s;
      &:hover { border-color: var(--border-light); }
      &.active { border-color: var(--accent-blue); background: var(--accent-blue)11; }
    }
    .history-build { font-family: var(--font-mono); color: var(--text-secondary); }
    .history-decision { font-weight: 700; font-family: var(--font-mono); }
    .history-date { color: var(--text-faint); font-size: 10px; }

    .inc-row {
      display: flex; align-items: center; gap: 8px;
      padding: 8px 0; border-bottom: 1px solid var(--border);
      &:last-child { border-bottom: none; }
    }
  `]
})
export class ProjectDetailComponent implements OnInit {
  @Input() id!: string;

  project: any     = null;
  incidents: any[] = [];
  allReports: any[] = [];
  latestReport: any = null;
  loading   = true;
  activeTab = 'rapport';

  // Parsed report fields
  rp: any = {};
  rawSecurity: any    = null;
  rawRemediation: any = null;
  devTasks: any[]     = [];
  checkedTasks        = 0;

  constructor(private api: ApiService, private toast: ToastService) {}

  ngOnInit() {
    this.api.getProject(this.id).subscribe({
      next: p => {
        this.project = p;
        this.loading = false;
        this.loadIncidents();
        this.loadReports();
      },
      error: () => {
        this.toast.error('Erreur', 'Projet introuvable');
        this.loading = false;
      }
    });
  }

  loadIncidents() {
    this.api.getIncidents({ projectId: this.id, size: 20 }).subscribe((r: any) => {
      this.incidents = r.content || r;
    });
  }

  loadReports() {
    this.api.getDecisions({ projectId: this.id }).subscribe({
      next: (r: any) => {
        const list: any[] = Array.isArray(r) ? r : [];
        this.allReports = list
          .filter(x => x.type === 'combined')
          .sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
        if (this.allReports.length > 0) {
          this.selectReport(this.allReports[0]);
        }
      },
      error: () => {}
    });
  }

  selectReport(r: any) {
    this.latestReport = r;
    this.rp           = this.parseReport(r.aiSummary);
    this.rawSecurity    = r.rawData?.security    || null;
    this.rawRemediation = r.rawData?.remediation || null;
    this.devTasks       = this.parseDevTasks(this.rp.developerActions);
    this.checkedTasks   = 0;
  }

  parseReport(summary: string): any {
    if (!summary) return {};
    const p: any = {};
    summary.split(' | ').forEach((part: string) => {
      part = part.trim();
      const buildMatch = part.match(/^Build #(\d+)$/);
      if (buildMatch) { p['build'] = buildMatch[1]; return; }
      if (part.startsWith('RAPPORT')) return;
      const idx = part.indexOf(':');
      if (idx > 0) {
        const key = part.substring(0, idx).trim();
        const val = part.substring(idx + 1).trim();
        if (key === 'Job')                p['job']              = val;
        else if (key === 'Branche')       p['branch']           = val;
        else if (key === 'DECISION')      p['decision']         = val;
        else if (key === 'Confiance') { const raw = parseFloat(val); p['confidence'] = isNaN(raw) ? val : (raw > 1 ? raw + '%' : Math.round(raw * 100) + '%'); }
        else if (key === 'Raison')        p['reason']           = val;
        else if (key === 'ERREURS')       p['errors']           = val;
        else if (key === 'AGENTS IA')     p['agentActions']     = val;
        else if (key === 'DEVELOPPEUR')   p['developerActions'] = val;
        else if (key === 'SECURITE')      p['security']         = val;
        else if (key === 'RECOMMANDATIONS') p['recommendations'] = val;
      }
    });
    return p;
  }

  parseDevTasks(raw: string): any[] {
    if (!raw) return [];
    // Handle array-like string: "[1. Task ([HAUTE]). 2. Task2 ([BASSE])]"
    const cleaned = raw.replace(/^\[|\]$/g, '');
    const matches = cleaned.match(/\d+\.\s[^0-9]+/g) || [];
    if (matches.length > 0) {
      return matches.map(m => {
        const priorityMatch = m.match(/\[(HAUTE|MOYENNE|BASSE)\]/i);
        const priority = priorityMatch ? priorityMatch[1].toUpperCase() : null;
        const text = m.replace(/\[.*?\]/g, '').replace(/^\d+\.\s*/, '').trim().replace(/\.$/, '');
        return { text, priority, done: false };
      });
    }
    // Fallback: one task
    return [{ text: cleaned, priority: null, done: false }];
  }

  toggleTask(i: number) {
    this.devTasks[i].done = !this.devTasks[i].done;
    this.checkedTasks = this.devTasks.filter(t => t.done).length;
  }

  copyReport() {
    const text = this.latestReport?.aiSummary || '';
    navigator.clipboard.writeText(text).then(() => {
      this.toast.success('Copié', 'Rapport copié dans le presse-papiers');
    });
  }

  getInfoRows() {
    if (!this.project) return [];
    return [
      { label: 'ID',              value: this.project.id },
      { label: 'Créé le',         value: new Date(this.project.createdAt).toLocaleDateString('fr-FR') },
      { label: 'Clé SonarQube',   value: this.project.sonarKey || '—' },
      { label: 'GitHub Repo',     value: this.project.githubRepo || '—' },
      { label: 'Jenkins Job',     value: this.project.jenkinsJobName || '—' },
      { label: 'Description',     value: this.project.description || '—' },
    ];
  }

  getHealthColor(score: number): string {
    if (score >= 80) return 'var(--accent-green)';
    if (score >= 60) return 'var(--accent-orange)';
    return 'var(--accent-red)';
  }

  getDecisionColor(decision: string): string {
    if (!decision) return 'var(--accent-blue)';
    if (decision === 'AUTO_FIX')    return 'var(--accent-green)';
    if (decision === 'BLOCK')       return 'var(--accent-red)';
    return 'var(--accent-orange)';
  }

  getSecurityColor(level: string): string {
    if (!level) return 'var(--text-muted)';
    const l = level.trim().toUpperCase();
    if (l === 'CRITICAL') return 'var(--accent-red)';
    if (l === 'HIGH')     return 'var(--accent-orange)';
    if (l === 'MEDIUM')   return 'var(--accent-yellow, #f59e0b)';
    return 'var(--accent-green)';
  }
}
